CREATE TABLE faultline.sources(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES faultline.workspaces(id),kind text NOT NULL,name text NOT NULL,namespace text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE faultline.imports(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,source_id uuid NOT NULL,record_kind text NOT NULL,format text NOT NULL,stage text NOT NULL,raw_key text NOT NULL,raw_bytes bigint NOT NULL,mapping_id uuid,normalized_key text,summary jsonb,snapshot_id uuid,job_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.sources(workspace_id,id));
CREATE TABLE faultline.mappings(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,import_id uuid NOT NULL,value jsonb NOT NULL,mapping_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id,import_id) REFERENCES faultline.imports(workspace_id,case_id,id));
CREATE TABLE faultline.snapshots(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,source_id uuid NOT NULL,import_id uuid NOT NULL,value jsonb NOT NULL,object_key text NOT NULL,content_hash text NOT NULL,withdrawn boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,import_id) REFERENCES faultline.imports(workspace_id,case_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.sources(workspace_id,id));
CREATE TABLE faultline.canonical_events(workspace_id uuid NOT NULL,case_id uuid NOT NULL,snapshot_id uuid NOT NULL,source_id uuid NOT NULL,event_id text NOT NULL,session_id text NOT NULL,event_name text NOT NULL,occurred_at timestamptz(6) NOT NULL,device text NOT NULL,excluded boolean NOT NULL,release_id text,PRIMARY KEY(workspace_id,snapshot_id,source_id,event_id),FOREIGN KEY(workspace_id,case_id,snapshot_id) REFERENCES faultline.snapshots(workspace_id,case_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.sources(workspace_id,id));
CREATE INDEX canonical_session_time ON faultline.canonical_events(workspace_id,snapshot_id,source_id,session_id,occurred_at);
CREATE TABLE faultline.metric_versions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,value jsonb NOT NULL,metric_hash text NOT NULL,state text NOT NULL,snapshot_id uuid,revision_id uuid,acknowledged_assumptions jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id),FOREIGN KEY(workspace_id,case_id,snapshot_id) REFERENCES faultline.snapshots(workspace_id,case_id,id));
CREATE TABLE faultline.comparisons(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,metric_hash text NOT NULL,snapshot_hash text NOT NULL,value jsonb NOT NULL,mix jsonb NOT NULL,job_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,job_id) REFERENCES faultline.jobs(workspace_id,case_id,id));
CREATE TABLE auth.recovery_capabilities(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES auth."user"(id),expires_at timestamptz NOT NULL,consumed_at timestamptz);
DO $scope$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sources','imports','mappings','snapshots','canonical_events','metric_versions','comparisons'] LOOP
 EXECUTE format('ALTER TABLE faultline.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE faultline.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON faultline.%I USING(workspace_id::text=current_setting(''faultline.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''faultline.workspace_id'',true))',t);
END LOOP;END $scope$;
GRANT SELECT,INSERT ON faultline.sources,faultline.imports,faultline.mappings,faultline.snapshots,faultline.canonical_events,faultline.metric_versions,faultline.comparisons TO faultline_api;
GRANT UPDATE(namespace) ON faultline.sources TO faultline_api;
GRANT UPDATE(stage,mapping_id,normalized_key,summary,snapshot_id,job_id) ON faultline.imports TO faultline_api;
GRANT UPDATE(state,snapshot_id,revision_id,acknowledged_assumptions) ON faultline.metric_versions TO faultline_api;
GRANT UPDATE(withdrawn) ON faultline.snapshots TO faultline_api;

